      "General English: Precis Writing; Letter Writing; Comprehension of given passages (MCQ); Grammar - Parts of Speech (MCQ); Correct usage and Vocabularies (MCQ); Formation of Sentence (MCQ) covering verbs and tenses, sentence structure, connectors, types of sentences, types of phrases and clauses, and narration.",
      "General Studies (MCQ): Current events of state, national and international importance; History of India and Indian National Movement; Indian and World Geography - Physical, Social, Economic Geography of India and the World; Indian Polity and Governance - Constitution, Political System, Public Policy, Duties & Rights Issues.",
      "General Studies (continued): Economic and Social Development, Sustainable Development, Poverty, Inclusion, Demographics, Social Sector initiatives and other related issues; General issues on Environment Ecology, Bio-diversity and Climate; General Science; and General awareness on Mizo culture, its heritage and society.",
