      "Technical Subject Paper-I, Unit B - Chemistry: Laws of Thermodynamics; order and molecularity of reactions; polythene, polystyrene, nylon and terylene; oxidation and reduction, oxidation number and redox reactions; carbohydrates, proteins, vitamins and nucleic acids; IUPAC nomenclature of mononuclear coordination compounds, isomerism, valence bond theory; transition elements; IUPAC nomenclature of organic compounds; surface chemistry - adsorption, colloidal solutions, Tyndall effect, Brownian movement, electrophoresis, emulsion.",
