      "Passed at least Higher Secondary (H.S+2) or equivalent examination from a recognized Board/University with minimum 35% marks in average, or passed Madhyamik examination with a Stenography Course from any ITI with 35% marks in Madhyamik; the qualifying marks are relaxable by 5% for all reserved category (SC/ST/Ex-serviceman/P.H) candidates.",
      "Knowledge of operating a computer with a certificate of minimum 3 months' duration from any Govt., Govt. recognized or Govt. registered Institution or University.",
