      "Preliminary Examination syllabus (GA(P&T) Notification No. F.35(11)-GA(P&T)/72(II) dated 14 March 2022), English - 30 marks: Use of appropriate Preposition and Article, Synonyms and Antonyms, Comprehension, Ordering of Words in a Sentence, Sporting of Errors etc.",
      "Preliminary, General Studies - 30 marks: General Knowledge with special reference to Tripura & North Eastern Region, Current Affairs of Local, National and International Importance, Simple Arithmetic, Mental Ability etc.",
      "Preliminary, Shorthand (English) - 40 marks: Introduction to Stenography; Consonants and their joining; Vowels, Diphthongs and Triphones, Grammalogues and Punctuation Signs; Alternative forms of 'R' and 'H', abbreviated 'W' Phraseography and Tick 'The'; Circles and Loops; Hooks (Initial and Final); Halving Principle and Doubling Principle; Compound Consonants, Dot and Tick 'H'; Diphones, Medial Semi-Circle, Essential Vowels, Upward & downward L, Upward and downward 'SH'; Prefixes and Suffixes; General Contractions, Special Contractions and Figure; Advanced Phraseography; Intersections.",
      "Main Examination (Annexure-I) is conducted as per the secondary (Madhyamik) standard in Paper-I English (100 marks, 3 hours), Paper-II Bengali or Alternative English (50 marks, 1.5 hours) and Paper-III General Knowledge & Current Affairs (100 marks, 3 hours), grand total 250 marks.",
      "Main, Paper-I (English): an exercise in composition - essay, report or letter of about 400 words from points or materials supplied; precis of a series of correspondence or summary of a given passage; translation from Bengali, Kokborok or Hindi as the case may be, to English; correction of sentences; punctuation; correct use of words and common phrases.",
