      "Main, Paper-III (General Knowledge & Current Affairs): questions to test the extent of a candidate's knowledge and capacity to express himself/herself correctly on matters of common knowledge and current events and problems with special reference to India; elementary knowledge of Indian History and Indian Geography may also be tested.",
