      "Applicants must be in good mental and bodily health, free from physical deformities and from diseases such as diabetes, heart disease, hernia, piles, respiratory diseases, knock-knee and flat foot, must not be colour blind or squint eyed, and must have distance vision of 6/6 in at least one eye and not poorer than 6/9 in the other without correction. Age is calculated only from the Matriculation/HSLC admit card or pass certificate.",
